package com.cuupe.backend.modules.workspace.controller;
import com.cuupe.backend.common.Result; import com.cuupe.backend.common.exception.ApiException; import com.cuupe.backend.modules.user.security.UserLoginByPassword; import com.cuupe.backend.modules.workspace.entity.WorkspaceMember; import com.cuupe.backend.modules.workspace.mapper.WorkspaceMemberMapper; import jakarta.validation.constraints.NotBlank; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/workspaces/{workspaceId}/members") @RequiredArgsConstructor public class WorkspaceMemberController { private final WorkspaceMemberMapper mapper; @GetMapping public Result<List<WorkspaceMember>> list(@PathVariable Long workspaceId,Authentication auth){return Result.success(mapper.findAccessible(workspaceId,userId(auth)));} @PatchMapping("/{memberId}") public Result<Void> role(@PathVariable Long workspaceId,@PathVariable Long memberId,@RequestBody RoleRequest request,Authentication auth){if(!List.of("ADMIN","MEMBER").contains(request.role()))throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_ROLE","成员角色不正确");if(mapper.updateRole(workspaceId,memberId,request.role(),userId(auth))==0)throw new ApiException(HttpStatus.FORBIDDEN,"MEMBER_WRITE_FORBIDDEN","没有修改成员角色的权限");return Result.success();} private Long userId(Authentication auth){return ((UserLoginByPassword)auth.getPrincipal()).getId();} public record RoleRequest(@NotBlank String role){} }